class ProfileViewModel : ViewModel() {
    fun loadProfile() {
        viewModelScope.launch {
            val user = async { api.getUser() }
            val posts = async { api.getPosts() }
            val friends = async { api.getFriends() }
            // all three run in parallel, all cancelled together if scope dies
            updateUi(user.await(), posts.await(), friends.await())
        }
    }
}

suspend fun loadDashboard() = supervisorScope {
    launch { runCatching { loadWeather() }.onFailure { showWeatherError() } }
    launch { runCatching { loadNews() }.onFailure { showNewsError() } }
    launch { runCatching { loadStocks() }.onFailure { showStocksError() } }
    // one widget failing does not cancel the others
}

val handler = CoroutineExceptionHandler { _, exception ->
    Log.e("App", "Uncaught: ${exception.message}")
}

viewModelScope.launch(handler) {
    try {
        riskyOperation()
    } catch (e: CancellationException) {
        throw e // never swallow this - rethrow to preserve cancellation
    } catch (e: Exception) {
        showError(e)
    }
}
